    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    # Each row of equally spaced marker cells becomes alternating marker/new color.
    # The inserted color is the first absent color following the marker color.
    for r, row in enumerate(grid):
        marks = [c for c, value in enumerate(row) if value != bg]
        if len(marks) < 2:
            continue
        marker = row[marks[0]]
        candidate = (marker + 1) % 10
        while candidate == bg or candidate == marker:
            candidate = (candidate + 1) % 10
        for a, b in zip(marks, marks[1:]):
            if b - a == 2 and row[b] == marker and row[a] == marker and row[a + 1] == bg:
                out[r][a + 1] = candidate
    return out
